local OverseaClubBossRankConfirmPopup = Class('OverseaClubBossRankConfirmPopup')
function OverseaClubBossRankConfirmPopup:__init()
    self.data = nil
    self.rewards = nil
end

function OverseaClubBossRankConfirmPopup:__delete()
    self.data = nil
    self.rewards = nil
end

function OverseaClubBossRankConfirmPopup:Awake()

end

function OverseaClubBossRankConfirmPopup:RefreshUI(params)
    if not isNull(params) and not isNull(params.data) then
        self.data = params.data
        local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
        local clubName = clubHomeDojo.name
        CfUtils.FillText(self.TextName,clubName)

        local clubHeadVo = ClubUtils.GetClubHeadVo(clubHomeDojo.avatar)
        if not isNull(clubHeadVo) then
            CfUtils.FillImage(self.ImgHead,clubHeadVo.photoPath)
        end

        CfUtils.FillText(self.ServerRank,self.data.clubRanking)
        CfUtils.FillText(self.ClubRank,self.data.myRanking)
        if table.count(self.data.rewards) > 0 then
            self.rewards = self.data.rewards
            self:RefreshGridView()
        end
    end
end

function OverseaClubBossRankConfirmPopup:RefreshGridView()
    local count = #self.rewards
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, count)
    end
end

function OverseaClubBossRankConfirmPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.rewards < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
        local data = self.rewards[index + 1]
        env:Reload(
                {
                    goodsId = data.goodsId,
                    text = "x" .. data.num,
                    isShowNo = true
                }
        )
        env:SetClickButtonAction(function(goodsId)
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if isTable(goodsVo) then
                GameUtils.ShowCommonTipsBoard(cell.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end
        end)
    end
    return cell
end

function OverseaClubBossRankConfirmPopup:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaClubBossRankConfirmPopup